import{_ as t,o,c as r,j as e,a as s}from"./chunks/framework.DdpBa4_E.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/80-反面教材.md","filePath":"books/attached/80-反面教材.md","lastUpdated":1794316978000}'),n={name:"books/attached/80-反面教材.md"};function d(c,a,l,_,i,p){return o(),r("div",null,[...a[0]||(a[0]=[e("h3",{id:"反面教材",tabindex:"-1"},[s("反面教材 "),e("a",{class:"header-anchor",href:"#反面教材","aria-label":'Permalink to "反面教材"'},"​")],-1),e("p",null,"玛莎和克雷格的故事，是焦虑——回避型亲密关系的一个典型的反面教材。克雷格显然不太希望有太多的亲密感，因此他总是不放过任何一个机会，在自己和玛莎之间制造屏障——在交往之初就表现得很不确定；让他们的关系模糊不清；“逼着”他才会结婚；贬低伴侣；抗拒性行为；以及其他的去激活策略。很显然，他属于回避型依恋风格。而玛莎恰好又是焦虑型依恋风格。她非常渴望接近克雷格，她积极推进两人的结婚进程，也深深陷入了两人的关系当中。她整天因为克雷格的行为而以泪洗面，无法自拔。即使是后来考虑要离婚，也是对这段关系另一种方式的关注。她情绪的快乐与低沉，完全取决于克雷格发出的信号，这是典型的焦虑型行为。不仅如此，她还会采取一些防御策略，比如说威胁对方要分手，但是从来没有付诸行动过。她的依恋机制长期处于激活状态，起码在他们恋爱的前几年，她对克雷格失去兴趣之前，一直都处于这种状态。",-1),e("p",null,"玛莎的故事充分说明了一点，如果两人在亲密关系中的需求截然不同，是一定会导致持续冲突的。克雷格期望保持距离，而玛莎渴望亲密。回避型风格的克雷格，自尊不断膨胀，从而导致焦虑型的玛莎陷入越来越严重的自我怀疑。但与此同时，他们之间又常有甜蜜的时刻，导致玛莎狠不下心来分手。比如说，克雷格在事情快要失控时，懂得如何通过深情与爱意安抚玛莎，虽然说这些失控的局面多半是由他造成的！总之他们的关系不断在疏离和亲密之间切换，这就是典型的焦虑——回避型亲密关系。",-1)])])}const h=t(n,[["render",d]]);export{f as __pageData,h as default};
